import json

# Try to parse the JSON for 1970 bulletin and find railroad retirement data
with open('/app/resources/treasury_bulletin_1970_06.json', 'r') as f:
    data = json.load(f)

# Search for railroad retirement data in the JSON
def search_nested(d, target):
    results = []
    if isinstance(d, dict):
        for k, v in d.items():
            if target.lower() in k.lower():
                results.append((k, v))
            results.extend(search_nested(v, target))
    elif isinstance(d, list):
        for item in d:
            results.extend(search_nested(item, target))
    return results

results = search_nested(data, 'railroad')
print(f"Found {len(results)} results for 'railroad'")
for r in results[:10]:
    print(f"  Key: {r[0]}, Value: {str(r[1])[:100]}")
EOF
